)
INSERT INTO public.matturo_modifiers (item_id,group_id,id,name,price_cents,max,position)
SELECT s.item_id,s.group_id,(m->>0)::uuid,m->>1,(m->>2)::integer,(m->>3)::integer,(m->>4)::integer
FROM source s CROSS JOIN LATERAL jsonb_array_elements(s.modifiers) m
ON CONFLICT (item_id,group_id,id) DO NOTHING;